   "\nCREATE INDEX \"leave_req_status_idx\" ON \"leave_requests\" USING btree (\"status\");",
   "\nCREATE INDEX \"shift_assign_emp_idx\" ON \"shift_assignments\" USING btree (\"employee_id\",\"effective_from\");",
