   "\nCREATE UNIQUE INDEX \"alloc_pair_uq\" ON \"bill_allocations\" USING btree (\"exit_bill_id\",\"entry_bill_id\");",
   "\nCREATE INDEX \"alloc_entry_idx\" ON \"bill_allocations\" USING btree (\"entry_bill_id\");",
